use efevm::op::opcodes_markdown;
use efevm::Op;

const OPCODES_PATH: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/OPCODES.md");

#[test]
fn write_opcodes_md() {
    let mut text = String::from(
        "<!-- Generated by `cargo test -p efevm --test opcodes`. Do not edit by hand. -->\n",
    );
    text.push_str(&opcodes_markdown());

    let existing = std::fs::read_to_string(OPCODES_PATH).unwrap_or_default();
    if existing != text {
        std::fs::write(OPCODES_PATH, &text).expect("failed to write OPCODES.md");
    }
}

#[test]
fn opcodes_md_lists_every_op() {
    let md = opcodes_markdown();
    for op in Op::ALL {
        assert!(
            md.contains(op.name()),
            "generated markdown is missing mnemonic {}",
            op.name()
        );
        let hex = format!("0x{:03X}", op.code());
        assert!(
            md.contains(&hex),
            "generated markdown is missing hex code {} for {}",
            hex,
            op.name()
        );
    }
}
